    CONSTRAINT postcorte_calidad_reporte_descuentos_check CHECK ((calidad_reporte_descuentos = ANY (ARRAY['SIN_DATOS'::text, 'EXCELENTE'::text, 'BUENO'::text, 'ACEPTABLE'::text, 'REVISAR'::text, 'CRITICO'::text]))),
